function benchmark(sortFn, inputs) {
  const runs = [];
  let total = 0, worst = 0;
  for (const input of inputs) {
    let comparisons = 0;
    const compare = function (x, y) { comparisons++; return x - y; };
    const result = sortFn(input.slice(), compare);
    let sorted = true;
    for (let i = 1; i < result.length; i++) {
      if (result[i - 1] > result[i]) { sorted = false; break; }
    }
    runs.push({ n: input.length, comparisons: comparisons, sorted: sorted });
    total += comparisons;
    if (comparisons > worst) worst = comparisons;
  }
  return { runs: runs, totalComparisons: total, maxComparisons: worst };
}

