function mergeSortBy(a, keyFn) {
  if (a.length <= 1) return a.slice();
  const mid = Math.floor(a.length / 2);
  const L = mergeSortBy(a.slice(0, mid), keyFn);
  const R = mergeSortBy(a.slice(mid), keyFn);
  const out = [];
  let i = 0, j = 0;
  while (i < L.length && j < R.length) {
    if (keyFn(L[i]) <= keyFn(R[j])) out.push(L[i++]);
    else out.push(R[j++]);
  }
  while (i < L.length) out.push(L[i++]);
  while (j < R.length) out.push(R[j++]);
  return out;
}

