function medianOfThree(a, lo, hi) {
  const mid = Math.floor((lo + hi) / 2);
  const trio = [[a[lo], lo], [a[mid], mid], [a[hi], hi]];
  trio.sort(function (x, y) { return x[0] < y[0] ? -1 : (x[0] > y[0] ? 1 : 0); });
  return trio[1][1];
}
